package me.ayuilos.miffan.ui.im.computer

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/*
 * Brand marks for the systems and networks the setup names. Apple and Linux (Tux) paths are from
 * Simple Icons 13.21.0 (CC0-1.0 icon data; the marks remain their owners' trademarks). The Windows
 * and Tailscale marks are drawn here from their geometric shapes. All are 24x24 and single-colour so
 * Icon() tints them; Tailscale's faded dots keep their own alpha under the tint.
 */

private fun brandIcon(name: String, build: ImageVector.Builder.() -> Unit): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).apply(build).build()

private fun ImageVector.Builder.pathData(data: String, alpha: Float = 1f) {
    addPath(PathParser().parsePathString(data).toNodes(), fill = SolidColor(Color.Black), fillAlpha = alpha)
}

private fun circle(cx: Float, cy: Float, r: Float) =
    "M${cx - r},${cy}a$r,$r 0 1,0 ${2 * r},0a$r,$r 0 1,0 ${-2 * r},0z"

internal val AppleLogo: ImageVector by lazy {
    brandIcon("Apple") { pathData(APPLE_PATH) }
}

internal val LinuxLogo: ImageVector by lazy {
    brandIcon("Linux") { pathData(LINUX_PATH) }
}

/** The four-pane Windows mark. */
internal val WindowsLogo: ImageVector by lazy {
    brandIcon("Windows") {
        pathData("M2,2h9.5v9.5h-9.5z M12.5,2h9.5v9.5h-9.5z M2,12.5h9.5v9.5h-9.5z M12.5,12.5h9.5v9.5h-9.5z")
    }
}

/** Tailscale's nine dots: the middle row and the bottom centre solid, the rest faded. */
internal val TailscaleLogo: ImageVector by lazy {
    brandIcon("Tailscale") {
        val solid = setOf(3f to 12f, 12f to 12f, 21f to 12f, 12f to 21f)
        for (y in listOf(3f, 12f, 21f)) for (x in listOf(3f, 12f, 21f)) {
            pathData(circle(x, y, 2.6f), alpha = if (x to y in solid) 1f else 0.25f)
        }
    }
}

/**
 * Cua's koala mark, used as is: Cua's brand rules allow only its black file on light backgrounds and its
 * white file on dark ones, so tint it with [cuaMarkColor], never a theme colour.
 */
internal val CuaMark: ImageVector by lazy {
    ImageVector.Builder("Cua", 24.dp, 24.dp, CUA_VIEWPORT, CUA_VIEWPORT).apply {
        CUA_PATHS.forEach { addPath(PathParser().parsePathString(it).toNodes(), fill = SolidColor(Color.Black)) }
    }.build()
}

/** The only two colours [CuaMark] may take. */
internal fun cuaMarkColor(dark: Boolean): Color = if (dark) Color.White else Color.Black

